export function applyBuyerReview(){
 const reviewed={};
 for(const [id,values]of Object.entries(copy)){
  if(!buyerCopy[id]||values.length!==locales.length)throw Error('Incomplete buyer translation '+id);
  reviewed[buyerCopy[id]]=Object.fromEntries(locales.map((locale,i)=>[locale,values[i]]));
 }
 for(const [key,values]of Object.entries(interfaceReview))reviewed[key]=Object.fromEntries(locales.map((locale,i)=>[locale,values[i]]));
 for(const [key,values]of Object.entries(reviewed))if(key.endsWith(' ↗')){
  const base=key.slice(0,-2);
  reviewed[base]=Object.fromEntries(locales.map(locale=>[locale,values[locale].replace(/\s*↗$/u,'')]));
  reviewed[base+' | ZUFEK']=Object.fromEntries(locales.map(locale=>[locale,reviewed[base][locale]+' | ZUFEK']));
 }
 for(const [path,fields]of Object.entries(metadataReview)){
  for(const [index,values]of fields.entries()){
   const key=buyerMetadata[path][index];
   reviewed[key]=Object.fromEntries(locales.map((locale,i)=>[locale,values[i]]));
   if(index===0)reviewed[key+' | ZUFEK']=Object.fromEntries(locales.map((locale,i)=>[locale,values[i]+' | ZUFEK']));
  }
 }
 for(const locale of locales){
  const file='translations/'+locale+'.json';const dictionary=JSON.parse(fs.readFileSync(file,'utf8'));
  for(const [key,values]of Object.entries(reviewed))dictionary[key]=values[locale];
  fs.writeFileSync(file,JSON.stringify(dictionary,null,2)+'\n');
 }
 fs.writeFileSync('translations/buyer-review.json',JSON.stringify(reviewed,null,2)+'\n');
 return reviewed;
}

